package vn.covie.admin.api;
import java.util.UUID; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; import vn.covie.admin.api.dto.*; import vn.covie.admin.application.AdminReadService; import vn.covie.orders.api.dto.OrderDetailResponse; import vn.covie.orders.application.OrderReadService; import vn.covie.orders.model.*;
@RestController @RequestMapping("/api/v1/admin/orders") public class AdminOrderController {private final AdminReadService reads;private final OrderReadService orderReads;public AdminOrderController(AdminReadService reads,OrderReadService orderReads){this.reads=reads;this.orderReads=orderReads;}@GetMapping public ResponseEntity<AdminPageResponse<AdminOrderSummaryResponse>> list(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="50")int size,@RequestParam(required=false)OrderStatus status,@RequestParam(required=false)OrderType type,@RequestParam(required=false)UUID merchantId,@RequestParam(required=false)UUID buyerUserId,@RequestParam(required=false)String orderCode,@RequestParam(required=false)String sort){return ResponseEntity.ok().header("Cache-Control","private, no-store").body(reads.orders(page,size,status,type,merchantId,buyerUserId,orderCode,sort));}@GetMapping("/{orderId}") public ResponseEntity<OrderDetailResponse> detail(@PathVariable UUID orderId){return ResponseEntity.ok().header("Cache-Control","private, no-store").body(orderReads.detail(orderId));}@GetMapping("/{orderId}/events") public ResponseEntity<java.util.List<AdminOrderEventResponse>> events(@PathVariable UUID orderId){return ResponseEntity.ok().header("Cache-Control","private, no-store").body(reads.orderEvents(orderId));}}
